\begin{quote}
{Whenever $v_1,v_2,\ldots\in D(T)$ satisfy $v_n\xrightarrow{X}x$ and $Tv_n\xrightarrow{Y}y$ for some $x\in X$ and $y\in Y$, then $x\in D(T)$ and $Tx=y$.}
\end{quote}

translated_text:
\begin{quote}
{只要 $v_1,v_2,\ldots\in D(T)$ 对某些 $x\in X$ 和 $y\in Y$ 满足 $v_n\xrightarrow{X}x$ 及 $Tv_n\xrightarrow{Y}y$, 就有 $x\in D(T)$ 且 $Tx=y$.}
\end{quote}

